import{_ as o,o as t,c as s,a0 as a}from"./chunks/framework.CA5B_wS4.js";const h=JSON.parse('{"title":"Install GOKZ","description":"Installation guide for GOKZ","frontmatter":{"title":"Install GOKZ","description":"Installation guide for GOKZ"},"headers":[],"relativePath":"guides/install-gokz.md","filePath":"guides/install-gokz.md"}'),l={name:"guides/install-gokz.md"};function i(n,e,r,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h1><ol><li>This guide assumes that you have a working CS:GO server.</li><li>This guide assumes that you have access to the server files.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you are asked to overwrite files at any point in the guide, accept the overwrites.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you are having trouble with a step, try the <strong>#support</strong> channel in <a href="https://discord.gg/csgokz" target="_blank" rel="noreferrer">our Discord server</a>. <br>Be sure to mention which step you are having trouble with and include as much information as possible, including the error logs from <code>csgo/addons/sourcemod/logs/errors_********.log</code>.</p></div><h2 id="_1-installing-metamod-source" tabindex="-1">1. Installing Metamod:Source <a class="header-anchor" href="#_1-installing-metamod-source" aria-label="Permalink to &quot;1. Installing Metamod:Source&quot;">​</a></h2><ol><li><p>Start by downloading <a href="https://www.sourcemm.net/downloads.php?branch=stable" target="_blank" rel="noreferrer">Metamod:Source</a>.</p></li><li><p>Extract the files into your server&#39;s <code>csgo</code> directory.</p></li><li><p>You should now have Metamod:Source installed and working.</p></li></ol><div class="info custom-block"><p class="custom-block-title">Confirm this step</p><p>Restart your server and type <code>meta version</code> in the server console. <br>You should see the following line in the output: <code>Loaded As: Valve Server Plugin</code>.</p></div><h2 id="_2-installing-sourcemod" tabindex="-1">2. Installing SourceMod <a class="header-anchor" href="#_2-installing-sourcemod" aria-label="Permalink to &quot;2. Installing SourceMod&quot;">​</a></h2><ol><li><p>Start by downloading <a href="https://sourcemod.net/downloads.php?branch=stable" target="_blank" rel="noreferrer">SourceMod</a>.</p></li><li><p>Extract the files into your server&#39;s <code>csgo</code> directory.</p></li><li><p>You should now have SourceMod installed and working.</p></li></ol><div class="info custom-block"><p class="custom-block-title">Confirm this step</p><p>Restart your server and type <code>sm version</code> in the server console. <br>You should see the following line in the output: <code>SourceMod Version Information</code>.</p></div><h2 id="_3-installing-movementapi" tabindex="-1">3. Installing MovementAPI <a class="header-anchor" href="#_3-installing-movementapi" aria-label="Permalink to &quot;3. Installing MovementAPI&quot;">​</a></h2><ol><li><p>Start by downloading the latest release of <a href="https://github.com/danzayau/MovementAPI/releases" target="_blank" rel="noreferrer">MovementAPI</a>.</p></li><li><p>Extract the files into your server&#39;s <code>csgo</code> directory.</p></li><li><p>You should now have MovementAPI installed and working.</p></li></ol><div class="info custom-block"><p class="custom-block-title">Confirm this step</p><p>Restart your server and type <code>sm plugins list</code> in the server console. <br>You should see the following line in the output: <code>MovementAPI (2.2.0)</code>.</p></div><h2 id="_4-installing-gokz" tabindex="-1">4. Installing GOKZ <a class="header-anchor" href="#_4-installing-gokz" aria-label="Permalink to &quot;4. Installing GOKZ&quot;">​</a></h2><ol><li><p>Start by downloading the latest <strong>non-upgrade</strong> release of <a href="https://github.com/KZGlobalTeam/gokz/releases" target="_blank" rel="noreferrer">GOKZ</a>.</p></li><li><p>Extract the files into your server&#39;s <code>csgo</code> directory.</p></li><li><p>Open <code>csgo/addons/sourcemod/configs/databases.cfg</code> in a text editor and add the following lines:</p></li></ol><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;gokz&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;driver&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;sqlite&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;database&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;gokz-sqlite&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Make sure to paste this BEFORE the last existing <code>}</code> character in the file.</p></div><ol start="4"><li>You should now have GOKZ installed and working.</li></ol><div class="info custom-block"><p class="custom-block-title">Confirm this step</p><p>Restart your server and type <code>sm plugins list</code> in the server console. <br>You should see the following line in the output: <code>GOKZ-Core (3.2.0)</code>.</p></div><h2 id="_5-gokz-is-installed" tabindex="-1">5. GOKZ is installed <a class="header-anchor" href="#_5-gokz-is-installed" aria-label="Permalink to &quot;5. GOKZ is installed&quot;">​</a></h2><p>You&#39;ve finished installing GOKZ, the next steps are not required for a functional GOKZ server.</p><h2 id="_6-useful-plugins-optional" tabindex="-1">6. Useful plugins (optional) <a class="header-anchor" href="#_6-useful-plugins-optional" aria-label="Permalink to &quot;6. Useful plugins (optional)&quot;">​</a></h2><p>Install other useful plugins from the <a href="/csgo-docs/guides/useful-plugins">Useful plugins</a> guide.</p><h2 id="_7-apply-for-global-whitelist-optional" tabindex="-1">7. Apply for Global Whitelist (optional) <a class="header-anchor" href="#_7-apply-for-global-whitelist-optional" aria-label="Permalink to &quot;7. Apply for Global Whitelist (optional)&quot;">​</a></h2><p>Follow the <a href="/csgo-docs/guides/global-gokz">GOKZ global whitelist guide</a> guide to get your server whitelisted.</p>`,25)])])}const g=o(l,[["render",i]]);export{h as __pageData,g as default};
